// Procesar datos del API y eventos de calendario
const allInputs = $input.all();

let calendarEvents = [];
let dbHolidays = [];
let weekSchedule = null;

// Separar eventos de calendario y respuesta del API
allInputs.forEach(item => {
  if (item.json.data && item.json.data.holidays) {
    // Es la respuesta del API de WordPress
    dbHolidays = item.json.data.holidays || [];
    weekSchedule = item.json.data.weekSchedule || {};
  } else if (item.json.start) {
    // Es un evento del calendario
    calendarEvents.push(item.json);
  }
});

return [{
  json: {
    calendarEvents: calendarEvents,
    dbHolidays: dbHolidays,
    weekSchedule: weekSchedule
  }
}];

// Generar slots disponibles usando configuración dinámica de WordPress
const inputData = $input.first().json;
const existingEvents = inputData.calendarEvents || [];
const dbHolidays = inputData.dbHolidays || [];
const weekSchedule = inputData.weekSchedule || {};
const occupiedSlots = new Set();

// Mapear eventos existentes
if (Array.isArray(existingEvents)) {
  existingEvents.forEach(event => {
    if (event.start && event.start.dateTime) {
      occupiedSlots.add(event.start.dateTime.substring(0, 16));
    }
  });
}

// Definir feriados base de Chile (formato: 'YYYY-MM-DD')
// Estos se combinan con los de la configuración de WordPress
const feriadosBase = [
  // 2025
  '2025-01-01', // Año Nuevo
  '2025-04-18', // Viernes Santo
  '2025-04-19', // Sábado Santo
  '2025-05-01', // Día del Trabajador
  '2025-05-21', // Día de las Glorias Navales
  '2025-06-29', // San Pedro y San Pablo (movido)
  '2025-07-16', // Día de la Virgen del Carmen
  '2025-08-15', // Asunción de la Virgen
  '2025-09-18', // Independencia Nacional
  '2025-09-19', // Día de las Glorias del Ejército
  '2025-09-20', // Feriado adicional (puente)
  '2025-10-12', // Encuentro de Dos Mundos (movido)
  '2025-10-31', // Día de las Iglesias Evangélicas
  '2025-11-01', // Día de Todos los Santos
  '2025-12-08', // Inmaculada Concepción
  '2025-12-25', // Navidad
  // 2026
  '2026-01-01', // Año Nuevo
  '2026-04-03', // Viernes Santo
  '2026-04-04', // Sábado Santo
  '2026-05-01', // Día del Trabajador
  '2026-05-21', // Día de las Glorias Navales
  '2026-06-29', // San Pedro y San Pablo
  '2026-07-16', // Día de la Virgen del Carmen
  '2026-08-15', // Asunción de la Virgen
  '2026-09-18', // Independencia Nacional
  '2026-09-19', // Día de las Glorias del Ejército
  '2026-10-12', // Encuentro de Dos Mundos
  '2026-10-31', // Día de las Iglesias Evangélicas
  '2026-11-01', // Día de Todos los Santos
  '2026-12-08', // Inmaculada Concepción
  '2026-12-25'  // Navidad
];

// Combinar feriados base con los de la configuración de WordPress
const todosLosFeriados = [...feriadosBase, ...dbHolidays];
const feriadosSet = new Set(todosLosFeriados);

// Mapeo de días
const dayNames = ['sunday', 'monday', 'tuesday', 'wednesday', 'thursday', 'friday', 'saturday'];
const dias = ['domingo', 'lunes', 'martes', 'miércoles', 'jueves', 'viernes', 'sábado'];
const meses = ['enero', 'febrero', 'marzo', 'abril', 'mayo', 'junio', 'julio', 'agosto', 'septiembre', 'octubre', 'noviembre', 'diciembre'];

const availableSlots = [];
const now = new Date();

// Generar slots para los próximos 14 días
for (let day = 1; day <= 14; day++) {
  const date = new Date(now);
  date.setDate(date.getDate() + day);

  const dayOfWeek = date.getDay();
  const dayName = dayNames[dayOfWeek];

  // Verificar si el día está habilitado en la configuración
  const dayConfig = weekSchedule[dayName] || { enabled: false };
  if (!dayConfig.enabled) continue;

  // Verificar si es feriado
  const dateKey = date.toISOString().split('T')[0];
  if (feriadosSet.has(dateKey)) continue;

  // Obtener horarios de inicio y fin del día
  const startTime = dayConfig.start || '09:00';
  const endTime = dayConfig.end || '18:00';

  // Extraer horas de inicio y fin
  const [startHour] = startTime.split(':').map(Number);
  const [endHour] = endTime.split(':').map(Number);

  // Generar slots cada hora dentro del rango configurado
  for (let hour = startHour; hour < endHour; hour++) {
    const slotDate = new Date(date);
    slotDate.setHours(hour, 0, 0, 0);

    const slotKey = slotDate.toISOString().substring(0, 16);

    if (!occupiedSlots.has(slotKey)) {
      availableSlots.push({
        date: slotDate.toISOString().split('T')[0],
        time: hour + ':00',
        datetime: slotDate.toISOString(),
        displayDate: dias[dayOfWeek] + ' ' + slotDate.getDate() + ' de ' + meses[slotDate.getMonth()],
        displayTime: hour + ':00 hrs'
      });
    }
  }
}

// Limitar a los próximos 10 slots disponibles
return availableSlots.slice(0, 10).map(slot => ({ json: slot }));

