// Formatear slots para mensaje de WhatsApp
const slots = $input.all();

let slotsText = '📅 *Horarios disponibles:*\n\n';

slots.forEach((slot, index) => {
  slotsText += (index + 1) + '. ' + slot.json.displayDate + ' a las ' + slot.json.displayTime + '\n';
});

slotsText += '\nResponde con el número del horario que prefieras.';

const phoneNumber = $node['Appointments Webhook'].json.body.phoneNumber;
const phoneNumberId = $node['Appointments Webhook'].json.body.phoneNumberId;

return {
  json: {
    slotsMessage: slotsText,
    slots: slots.map(s => s.json),
    phoneNumber: phoneNumber,
    phoneNumberId: phoneNumberId
  }
};

